<style scoped>
/*
 * 尺寸写在这里而不是 custom.css：scoped 会带上属性选择器（0,2,0），
 * 稳压 `.vp-doc svg` 一类的元素级规则，也不用再往全局样式里添一条。
 */
.dl-icon {
  flex: 0 0 auto;
  width: 16px;
  height: 16px;
}

/*
 * 云标比箭头「矮」：24 的框里它只占 5.5→20.5 那段，图形横向铺满。
 * 给同样的 16px 会显得比旁边的字小一号，放到 18px 才和箭头视觉等重。
 * 不上色 —— 用 `fill="currentColor"` 跟着按钮文字走（浅色近黑 / 深色近白）。
 */
.dl-icon--cloudflare {
  width: 18px;
  height: 18px;
}

/* GitHub 章鱼猫是实心圆，墨铺满整框，比箭头显重；收一号到 15px */
.dl-icon--github {
  width: 15px;
  height: 15px;
}

/*
 * Apple 标反过来：它的墨几乎铺满整个 24 的框（0→23.4），给 16px 就比旁边的字高出一截。
 * 收到 14px，墨高 ≈ 13.7px，和 16px 正文的视觉高度对齐。
 */
.dl-icon--apple {
  width: 14px;
  height: 14px;
}

/*
 * 平台标按「墨高对齐」而不是「框对齐」：几个标的墨占框的比例差得很远，
 * 同框不同高。目标是它们的墨高都落在 13px 上下。
 *   Windows 四格旗铺满 0→24，给 13px 就是 13px；
 *   Linux 企鹅同样从 0 画到 24，按 Apple 标的口径给 14px；
 *   Android 机器人头是横的（墨高只占框的 0.6），所以要给到 18px 才有 10.7px 高。
 */
.dl-icon--windows {
  width: 13px;
  height: 13px;
}

.dl-icon--linux {
  width: 14px;
  height: 14px;
}

.dl-icon--android {
  width: 18px;
  height: 18px;
}
</style>
